10: export function formatMaterialDateTime(iso: string): string {
11:   const parsed = new Date(iso);
12:   if (Number.isNaN(parsed.getTime())) return iso;
13:   return new Intl.DateTimeFormat('zh-CN', {
14:     year: 'numeric',
15:     month: '2-digit',
16:     day: '2-digit',
17:     hour: '2-digit',
18:     minute: '2-digit',
